#include <iostream>
#include <atomic>
#include <thread>
#include <vector>

std::atomic<int> cnt{0};

int main() {
    std::vector<std::thread> ts;
    for (int i = 0; i < 4; ++i)
        ts.emplace_back([]{ for (int k = 0; k < 2500; ++k) cnt.fetch_add(1, std::memory_order_relaxed); });
    for (auto& t : ts) t.join();
    std::cout << "cnt=" << cnt.load();   // 4*2500=10000，确定性
}
